typeScriptFunctionUsageExample:
import { isPlainObject } from "@type-check/guards";

const input: unknown = JSON.parse('{"a":1}');

if (isPlainObject(input)) {
  // input is a plain object here
  console.log(Object.keys(input));
} else {
  console.log("Not a plain object");
}

console.log(isPlainObject({})); // true
console.log(isPlainObject([])); // false
console.log(isPlainObject(null)); // false

typeScriptObjectUsageExample:
import { isPlainObject } from "@type-check/guards";

type Config = { debug?: boolean };

function readConfig(value: unknown): Config {
  if (isPlainObject(value)) {
    const v = value as Record<string, unknown>;
    return {
      debug: typeof v.debug === "boolean" ? v.debug : undefined
    };
  }
  return {};
}

console.log(readConfig({ debug: true }));
console.log(readConfig(["debug"]));
